from __future__ import annotations

from typing import Any

VERDICT_PASSED = "TESTS_PASSED"
VERDICT_INCONCLUSIVE = "INCONCLUSIVE"

LIMITATIONS = [
    "The patch is a deterministic demo patch, not generated by an AI model.",
    "Only the bundled fixture is executed; arbitrary repositories are not accepted.",
    "Passing this test suite is evidence, not a proof of universal correctness.",
]

REPORT_KEYS = frozenset(
    {
        "status",
        "scenario",
        "repository",
        "mode",
        "summary",
        "verdict",
        "baseline",
        "verification",
        "patch",
        "limitations",
    }
)


def decide_verdict(baseline: dict[str, Any], verification: dict[str, Any]) -> str:
    """A fix is verified only when the baseline failed and the post-patch run passed."""
    if baseline.get("passed") is False and verification.get("passed") is True:
        return VERDICT_PASSED
    return VERDICT_INCONCLUSIVE


def build_report(
    *,
    scenario: str,
    repository: str,
    mode: str,
    baseline: dict[str, Any],
    verification: dict[str, Any],
    patch: dict[str, str],
) -> dict[str, Any]:
    """Build the investigation report. Keys match the existing API contract."""
    verdict = decide_verdict(baseline, verification)
    verified = verdict == VERDICT_PASSED
    return {
        "status": "complete",
        "scenario": scenario,
        "repository": repository,
        "mode": mode,
        "summary": (
            "The baseline reproduced a failure, and the demo patch passed the bundled tests."
            if verified
            else "The expected baseline-to-passing-test sequence did not occur. Inspect the test output."
        ),
        "verdict": verdict,
        "baseline": baseline,
        "verification": verification,
        "patch": patch,
        "limitations": list(LIMITATIONS),
    }
